#!/usr/bin/env node
// The components-only example from packed tarballs: @oddkin/core, @oddkin/tokens, and
// @oddkin/components are packed and installed into a consumer outside the workspace, and the
// page is copied there. Its import map is generated by walking the installed modules through
// each package's `exports` (default, production conditions), its token stylesheet must be a
// published file, and its CSP hash is recomputed. Run after `npm run build`.
//
//   node examples/components-only/packed.mjs --port 4174
//
// Serves the consumer; packing starts on the first request other than /__health, and
// /__ready reports the installed packages and import map (e2e/components-only.spec.ts).
import { execFileSync } from 'node:child_process';
import { createHash } from 'node:crypto';
import { createServer } from 'node:http';
import { copyFile, mkdir, mkdtemp, readFile, rm, stat, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { dirname, extname, join, normalize, relative, resolve, sep } from 'node:path';
import { fileURLToPath } from 'node:url';
import { init, parse } from 'es-module-lexer';

const here = dirname(fileURLToPath(import.meta.url));
const root = resolve(here, '../..');
const PACKAGES = ['core', 'tokens', 'components'];
const PREFIX = 'oddkin-components-only-';

const npmCli = process.env['npm_execpath']?.endsWith('.js')
  ? process.env['npm_execpath']
  : join(dirname(process.execPath), 'node_modules', 'npm', 'bin', 'npm-cli.js');
const npm = (args, cwd) =>
  execFileSync(process.execPath, [npmCli, ...args], {
    cwd,
    encoding: 'utf8',
    stdio: ['ignore', 'pipe', 'pipe'],
  });

/** The file a bare specifier resolves to through the installed package's `exports`. */
async function resolveSpecifier(site, specifier) {
  const match = /^(@[^/]+\/[^/]+)(?:\/(.+))?$/.exec(specifier);
  if (!match) throw new Error(`${specifier}: not an installed scoped package`);
  const dir = join(site, 'node_modules', ...match[1].split('/'));
  const manifest = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  const target = manifest.exports?.[match[2] ? `./${match[2]}` : '.'];
  const path = typeof target === 'string' ? target : target?.default;
  if (!path) throw new Error(`${specifier}: not exported by ${match[1]}`);
  return join(dir, path);
}

const urlOf = (site, file) => `./${relative(site, file).split(sep).join('/')}`;

/** Import map for everything reachable from the page script, bare specifiers only. */
async function importMap(site, entry) {
  await init;
  const imports = {};
  const seen = new Set();
  const visit = async (file) => {
    if (seen.has(file)) return;
    seen.add(file);
    const [records] = parse(await readFile(file, 'utf8'));
    for (const { specifier } of records) {
      if (!specifier) continue;
      if (specifier.startsWith('.')) {
        await visit(resolve(dirname(file), specifier));
        continue;
      }
      const target = await resolveSpecifier(site, specifier);
      imports[specifier] = urlOf(site, target);
      await visit(target);
    }
  };
  await visit(entry);
  return Object.fromEntries(Object.entries(imports).sort(([a], [b]) => a.localeCompare(b)));
}

/** A workspace path such as ../../packages/tokens/dist/css/default.css as its published file. */
async function publishedFile(site, path) {
  const [, name, file] = /^\.\.\/\.\.\/packages\/([^/]+)\/(.+)$/.exec(path) ?? [];
  if (!name) return path;
  const dir = join(site, 'node_modules', '@oddkin', name);
  const manifest = JSON.parse(await readFile(join(dir, 'package.json'), 'utf8'));
  const exported = Object.values(manifest.exports ?? {}).some(
    (target) => (typeof target === 'string' ? target : target?.default) === `./${file}`,
  );
  if (!exported) throw new Error(`${path}: not a published file of @oddkin/${name}`);
  return urlOf(site, join(dir, file));
}

/**
 * Pack, install, and copy the page into `work` (emptied first; a new temporary directory when
 * omitted). Returns the consumer directory and what it contains.
 */
export async function packConsumer(work) {
  if (work) {
    await rm(work, { recursive: true, force: true });
    await mkdir(work, { recursive: true });
  } else work = await mkdtemp(join(tmpdir(), PREFIX));
  const tarballs = PACKAGES.map((name) => {
    const [info] = JSON.parse(
      npm(['pack', '--json', '--pack-destination', work], join(root, 'packages', name)),
    );
    return join(work, info.filename);
  });
  const site = join(work, 'site');
  await mkdir(site);
  await writeFile(
    join(site, 'package.json'),
    JSON.stringify({ name: 'components-only-consumer', private: true, type: 'module' }),
  );
  npm(['install', '--no-audit', '--no-fund', '--ignore-scripts', ...tarballs], site);
  const installed = [];
  const walk = (deps = {}) => {
    for (const [name, info] of Object.entries(deps)) {
      installed.push(name);
      walk(info.dependencies);
    }
  };
  walk(JSON.parse(npm(['ls', '--all', '--json'], site)).dependencies);

  for (const file of ['main.js', 'styles.css']) await copyFile(join(here, file), join(site, file));
  const imports = await importMap(site, join(site, 'main.js'));
  const map = `\n${JSON.stringify({ imports }, null, 2)}\n`;
  const hash = createHash('sha256').update(map).digest('base64');
  let html = await readFile(join(here, 'index.html'), 'utf8');
  html = html
    .replace(/(<script type="importmap">)[\s\S]*?(<\/script>)/, `$1${map}$2`)
    .replace(/'sha256-[^']+'/, `'sha256-${hash}'`);
  for (const [, href] of html.matchAll(/href="([^"]+)"/g))
    html = html.replace(`href="${href}"`, `href="${await publishedFile(site, href)}"`);
  if (html.includes('../../')) throw new Error('index.html still references the workspace');
  await writeFile(join(site, 'index.html'), html);
  return { work, site, installed: [...new Set(installed)].sort(), imports };
}

const types = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.map': 'application/json; charset=utf-8',
};

function serve(port) {
  let packed;
  // One directory per port: a server stopped without cleanup (Windows) leaves at most one copy.
  const ready = () => (packed ??= packConsumer(join(tmpdir(), `${PREFIX}${port}`)));
  const server = createServer(async (request, response) => {
    const url = new URL(request.url ?? '/', 'http://localhost');
    if (url.pathname === '/__health') return void response.writeHead(200).end('ok');
    let consumer;
    try {
      consumer = await ready();
    } catch (error) {
      return void response.writeHead(500).end(String(error.stderr || error.message || error));
    }
    if (url.pathname === '/__ready') {
      const { installed, imports } = consumer;
      response.writeHead(200, { 'content-type': types['.json'] });
      return void response.end(JSON.stringify({ installed, imports }));
    }
    let path = normalize(join(consumer.site, decodeURIComponent(url.pathname)));
    if (path !== consumer.site && !path.startsWith(consumer.site + sep))
      return void response.writeHead(403).end('Forbidden');
    try {
      if ((await stat(path)).isDirectory()) path = join(path, 'index.html');
      const body = await readFile(path);
      response.writeHead(200, {
        'content-type': types[extname(path)] ?? 'application/octet-stream',
      });
      response.end(body);
    } catch {
      response.writeHead(404).end('Not found');
    }
  });
  const stop = () => {
    server.close();
    const work = packed
      ? packed.then(
          (c) => c.work,
          () => undefined,
        )
      : Promise.resolve(undefined);
    work
      .then((dir) => dir && rm(dir, { recursive: true, force: true }))
      .finally(() => process.exit(0));
  };
  process.on('SIGINT', stop);
  process.on('SIGTERM', stop);
  server.listen(port, () =>
    console.log(`Packed components-only consumer at http://localhost:${port}/`),
  );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const portArg = process.argv.indexOf('--port');
  serve(portArg > -1 ? Number(process.argv[portArg + 1]) : 4174);
}
